#include <iostream>
using namespace std;

class FishBox {
    int* p;
public:
    FishBox(int v) { p = new int(v); }
    FishBox(const FishBox& other) { p = new int(*other.p); }
    ~FishBox() { delete p; }
    FishBox& operator=(const FishBox& other) {
        *p = *other.p;
        return *this;
    }
    int get() const { return *p; }
    void set(int v) { *p = v; }
};

int main() {
    FishBox a(5);
    FishBox b(2);
    b = a;
    a.set(8);
    cout << a.get() << " " << b.get() << endl;
    return 0;
}
